<template><div><el-breadcrumb separator="/"><el-breadcrumb-item to="/admin/reports">管理决策专题</el-breadcrumb-item><el-breadcrumb-item>排课策略与方案优化</el-breadcrumb-item></el-breadcrumb><h2 class="sa-page-title">排课策略与方案优化</h2><p class="sa-page-sub">基于实际课表描述时段分布和教师排课行为集中度，为新学年排课准备约束证据。</p><el-alert type="warning" :closable="false" show-icon title="当前只能分析实际分布，不能生成优化方案" :description="definition.boundary"/><el-skeleton :loading="loading" animated :rows="5"><div class="kpis"><div v-for="x in kpis" :key="x.label" class="kpi"><span>{{x.label}}<el-tooltip :content="x.help"><i>?</i></el-tooltip></span><b>{{x.value}}</b><small>{{x.note}}</small></div></div><div class="grid"><section class="sa-card"><div class="sa-card-title">星期—时段实际排课分布</div><el-table :data="data.cells" size="small"><el-table-column prop="weekday" label="星期"><template #default="{row}">星期{{weekday[row.weekday]}}</template></el-table-column><el-table-column prop="day_part" label="时段"/><el-table-column prop="meeting_count" label="排课记录数"/><el-table-column prop="lesson_count" label="教学班数"/><el-table-column prop="room_count" label="涉及教室数"/></el-table></section><section class="sa-card"><div class="sa-card-title">体育课与思政课时段分布</div><el-table :data="data.focus" size="small"><el-table-column prop="course_group" label="课程类别"/><el-table-column prop="weekday" label="星期"><template #default="{row}">星期{{weekday[row.weekday]}}</template></el-table-column><el-table-column prop="day_part" label="时段"/><el-table-column prop="meeting_count" label="排课记录数"/></el-table></section></div><section class="sa-card"><div class="sa-card-title">教师实际排课集中时段样本 <span class="extra">不是教师主动填报偏好</span></div><el-table :data="data.preferences" size="small"><el-table-column prop="staff_id" label="教师代码"/><el-table-column prop="weekday" label="最多出现星期"><template #default="{row}">星期{{weekday[row.weekday]}}</template></el-table-column><el-table-column prop="day_part" label="最多出现时段"/><el-table-column prop="meeting_count" label="该时段记录数"/><el-table-column prop="total" label="全部记录数"/><el-table-column label="集中度"><template #default="{row}">{{row.share}}%</template></el-table-column></el-table></section><section class="sa-card explain"><div class="sa-card-title">管理使用建议</div><p>先用高峰时段识别可能需要错峰核查的区域；用体育课、思政课分布检查重点课程时段是否过度集中；教师集中时段只作为排课沟通参考。新学年优化必须叠加班级冲突、教师不可用时间、课程连续节次、教室容量与类型等硬约束。</p></section></el-skeleton></div></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{http}from'@/utils/http';const loading=ref(true),data=reactive<any>({summary:{},cells:[],focus:[],preferences:[]}),definition=reactive<any>({});const weekday:any={1:'一',2:'二',3:'三',4:'四',5:'五',6:'六',7:'日'};const kpis=computed(()=>{const p=data.summary.peak;return[{label:'教学班',value:(data.summary.lessons||0)+' 个',note:'当前接入学期',help:'教学任务中的去重教学班。'},{label:'课程',value:(data.summary.courses||0)+' 门',note:'按课程代码去重',help:'当前教学任务涉及的去重课程。'},{label:'实际授课教师',value:(data.summary.teachers||0)+' 人',note:'按教师代码去重',help:'承担当前教学任务的教师人数。'},{label:'排课记录',value:(data.summary.meetings||0)+' 条',note:'周次—星期—节次',help:definition.meeting||''},{label:'排课最集中时段',value:p?`星期${weekday[p.weekday]}${p.day_part}`:'—',note:p?`${p.meeting_count}条记录`:'暂无',help:definition.peak||''} ]});onMounted(async()=>{try{const r=await http.get<any>('/v2/topics/schedule-strategy');Object.assign(data,r);Object.assign(definition,r.definition)}finally{loading.value=false}})</script>
<style scoped>.sa-page-title{margin-top:12px}.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:14px 0}.kpi{background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:15px}.kpi span,.kpi small{display:block;color:#64748b}.kpi b{display:block;font-size:23px;margin:6px 0}.kpi i{margin-left:4px;font-style:normal}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.sa-card{margin-bottom:14px}.explain p{font-size:13px;color:#475569;line-height:1.8}@media(max-width:1100px){.kpis{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}</style>
